export const MONUMENTS = JSON.parse("[{\"id\":\"n8518753448\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"В. И. Ленину\",\"x\":-2315.8,\"z\":-2545,\"subject\":\"Q1394\",\"inscription\":\"Здесь, в оперном зале Народного дома 4 июня (22 мая) 1917 г. на 1-м Всероссийском съезде крестьянских депутатов выступал с речью по аграрному вопросу Владимир Ильич Ленин. Здесь же 13 марта 1919 г. Владимир Ильич Ленин выступал на многолюдном митинге ...\"},{\"id\":\"n9020875522\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"Н. Г. Маркину\",\"x\":-2406.1,\"z\":-2574.1,\"subject\":\"Q4281959\",\"inscription\":\"Маркин Николай Григорьевич, 1893 года рождения, матрос Балтийского флота. В 1917 г. - член Центробалта, один из руководителей кронштадской организации РСДРП/б/. После победы Октябрьской революции работал в Народном комиссариате иностранных дел. ...\"},{\"id\":\"n339816778\",\"kind\":\"memorial\",\"sub\":\"war_memorial\",\"name\":\"Стерегущему\",\"x\":-1704,\"z\":-2568.3,\"material\":\"bronze\",\"startDate\":\"1911\",\"artist\":\"К. В. Изенберг\",\"wikidata\":\"Q18121501\",\"wikipedia\":\"ru:Памятник «Стерегущему»\",\"heritage\":\"2\"},{\"id\":\"n1559808836\",\"kind\":\"memorial\",\"name\":\"Зодчим\",\"x\":-1925.7,\"z\":-2569.2,\"description\":\"Растрелли, Росси, Трезини, Тома де Томон, Монферран, Баженов, Захаров, Воронихин\"},{\"id\":\"n5627192902\",\"kind\":\"artwork\",\"x\":-1819.3,\"z\":-2583.2},{\"id\":\"n10159824139\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"М. И. Кутузову\",\"x\":-3732.7,\"z\":-2585.3,\"subject\":\"Q185801\",\"inscription\":\"Здесь в Военной инженерной школе с 1757 по 1761 г.г. обучался и преподавал великий русский полководец Михаил Илларионович Кутузов\"}]");
